WITH src AS (SELECT *, INITCAP(TRIM(plan)) AS plan_title FROM subscriptions WHERE MONTH(end_date) IN (7, 8, 9)), summary AS (SELECT CASE WHEN monthly_fee >= 186 THEN 'high' WHEN monthly_fee >= 106 THEN 'mid' ELSE 'low' END AS monthly_fee_bucket, MAX(end_date) AS last_end_date FROM src GROUP BY CASE WHEN monthly_fee >= 186 THEN 'high' WHEN monthly_fee >= 106 THEN 'mid' ELSE 'low' END) SELECT * FROM summary ORDER BY monthly_fee_bucket DESC;
